def link_packages_to_schools(apps, schema_editor):
    """
    A best guess at each package's Schools: those whose main group ("<School> Staff", as
    School.create_groups names it) the package includes. Others can be set in Django admin;
    the report_package_access command lists packages with no School.
    """
    School = apps.get_model('loads', 'School')
    WorkPackage = apps.get_model('loads', 'WorkPackage')
    for school in School.objects.all():
        for package in WorkPackage.objects.filter(groups__name=f"{school.name} Staff").distinct():
            package.schools.add(school)


